<?php if($transitions): ?><form class="card border-0 p-4 mb-3" method="post" action="<?= site_url('admin/orders/'.$order['id'].'/status') ?>"><?= csrf_field() ?><h2 class="h5">Change order status</h2><?php if(in_array('shipped',$transitions,true)&&(!$shipment||!in_array($shipment['status'],['booked','picked_up','in_transit','delivered'],true))): ?><div class="alert alert-warning small">Book a shipment before marking this order shipped.</div><?php endif ?><select class="form-select mb-2" name="status" required><?php foreach($transitions as $status): ?><option value="<?= $status ?>"><?= ucfirst($status) ?></option><?php endforeach ?></select><textarea class="form-control mb-2" name="note" placeholder="Optional note"></textarea><button class="btn btn-success">Update</button></form><?php endif ?>
