<form class="card border-0 p-4 mb-3" method="post" action="<?= site_url('admin/orders/'.$order['id'].'/payment') ?>"><?= csrf_field() ?><h2 class="h5"><?= $order['payment_method_code']==='courier_condition'?'Advance delivery payment':'Full payment' ?></h2><p><?= esc($payment['status']??'N/A') ?><?php if(!empty($payment['transaction_id'])): ?><br>Reference: <?= esc($payment['transaction_id']) ?><?php endif ?><?php if($order['payment_method_code']==='courier_condition'): ?><br>Submitted amount: <?= format_bdt($payment['amount']??0) ?><?php endif ?></p><div class="d-flex gap-2"><button class="btn btn-success" name="status" value="paid"><?= $order['payment_method_code']==='courier_condition'?'Verify delivery payment':'Mark fully paid' ?></button><button class="btn btn-outline-danger" name="status" value="failed">Reject</button></div></form>
